{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Decursinol angelate, a closely transferable polycyclic methoxy/coumarin natural product, showed Cbrain/Cplasma >1.5 after oral dosing in rats, directly demonstrating meaningful CNS access despite multiple oxygen functionalities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tylocrebrine, a polyoxygenated aromatic alkaloid, rapidly accumulated in mouse brain with an AUCbrain of 2.1 µg·h/mL, supporting CNS penetration for this methoxy-rich polycyclic chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Decursin showed brain-to-plasma ratios >1.5 in rats after oral administration, providing direct in vivo evidence that related polycyclic aromatic ethers cross the BBB effectively.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "α-Allocryptopine, a polymethoxylated benzylisoquinoline-related alkaloid, was detected in rat CSF, confirming passage across the BBB despite extensive methoxylation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hernandezine, a highly methoxylated bisbenzylisoquinoline, reached brain concentrations nearly equal to plasma Cmax after intravenous dosing in rats, showing that multiple methoxy groups do not preclude meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer in vivo, CSF, and brain-uptake records for structurally related polyoxygenated polycyclic natural products demonstrate meaningful CNS access, and the physicochemical prior is also favorable (MW 432.5, logD 3.89, TPSA 75.6 Å², neutral at physiological pH).",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule.",
    "P-gp/BCRP efflux liability was not experimentally assessed for the query.",
    "The methoxy-rich structure may undergo rapid metabolism in vivo, which could affect systemic exposure magnitude but not intrinsic BBB passage."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

